sys_module.content:
import { gs, GlideAggregate } from '@servicenow/glide'

export function regleUniciteLogement(current, previous) {
    // Check if there are multiple active logement dossiers
    var ga = new GlideAggregate('x_snc_habitat_dossier_metier');
    ga.addQuery('demande_parente', '=', current.sys_id);
    ga.addEncodedQuery('type_fluxINlogement_atrium,bcc');
    ga.addQuery('active', '=', 'true');
    ga.addAggregate('COUNT', 'sys_id');
    ga.query();

    if (ga.next()) {
        var count = parseInt(ga.getAggregate('COUNT', 'sys_id'));
        if (count > 1) {
            current.setAbortAction(true);
            gs.addErrorMessage('Impossible de clôturer cette demande : plusieurs dossiers logement actifs existent (' + count + '). Veuillez clôturer les dossiers logement en doublon avant de fermer la demande.');
        }
    }
}
